insert into public.artists (id, name, bio, image_url, monthly_listeners) values
  ('6a6ec555-5807-52d7-b857-f56fd7620ef2', 'Mira Solenne', 'Mira Solenne writes small, patient piano pieces at night in a converted boathouse. Her records are built from first takes and left a little unpolished on purpose.', '/media/art/artist/mira-solenne.svg', 1284330),
  ('edd603e2-362b-5cb9-aba6-64d9682dda50', 'The Low Tides', 'A bedroom duo trading loops across two time zones. Dusty keys, soft drums, and the hiss of a cassette deck they refuse to replace.', '/media/art/artist/the-low-tides.svg', 3412908),
  ('509a37a2-23aa-53af-b948-32e8f941b9da', 'Kestrel & Vane', 'Two former arcade technicians making night-drive music with machines older than they are. Big drums, bigger chords, no apologies.', '/media/art/artist/kestrel-and-vane.svg', 2250117),
  ('e6cb788d-fcd8-5c17-a167-b44d21c07833', 'Juno Abara', 'DJ and producer known for long, warm sets that start slow and never quite peak. Grew up on her parents'' soul records and the hum of the night bus.', '/media/art/artist/juno-abara.svg', 1876045),
  ('7064a84c-6649-5878-a173-dfb12054a0d4', 'Halden Field', 'Field recordist turned composer. Halden Field records long, slow pieces meant to be played quietly while the weather changes outside.', '/media/art/artist/halden-field.svg', 734512),
  ('81f34c9b-8543-5174-acb0-3c0a0503d5a0', 'Bitwise Orchard', 'One person, one battered handheld console, and an orchard of tiny square waves. Bright melodies for imaginary adventure games.', '/media/art/artist/bitwise-orchard.svg', 529880),
  ('7ed04b6d-2751-53bf-82df-39cbe6d05f6b', 'Oda Merle', 'Producer and cellist whose records sit somewhere between a train window and a late dinner. Deep bass, slow drums, plucked strings.', '/media/art/artist/oda-merle.svg', 961204),
  ('50a43e29-4d77-5105-98e2-874ec0d0037e', 'The Lamplight Quartet', 'A house band that outlived its house. Brushes, upright bass, and a slightly out-of-tune electric piano, recorded after closing time.', '/media/art/artist/the-lamplight-quartet.svg', 418223);
