  ('dd281264-a0c3-57d1-9434-4f4b0d3a350b', '00000000-0000-4000-8000-00000000ed17', 'Nightfall Focus', 'Soft beats and patient keys for deep work after dark.', true, now() - interval '0 days'),
  ('e969b54c-a5b0-54a8-b3ce-c945fb01fda0', '00000000-0000-4000-8000-00000000ed17', 'Midnight Motorway', 'Neon-lit synths and steady drums for the long way home.', true, now() - interval '1 days'),
  ('d5be4464-0398-50c8-b784-e1f84325ac59', '00000000-0000-4000-8000-00000000ed17', 'Kitchen Floor Disco', 'Warm house grooves for cooking, cleaning or dancing in socks.', true, now() - interval '2 days'),
  ('bc10d5e6-7d33-55f0-90b2-b9d80737a154', '00000000-0000-4000-8000-00000000ed17', 'Quiet Hours', 'Ambient textures and gentle piano to slow everything down.', true, now() - interval '3 days'),
  ('6653c7a2-f0da-55c4-9fe0-f7bd24d3d1e4', '00000000-0000-4000-8000-00000000ed17', 'After Dark Jazz Club', 'Brushed drums, walking bass and a piano that has seen things.', true, now() - interval '4 days'),
